231	// pathFooterHeight is the Path footer in every state: the target bar (2), the
232	// tab row, a blank line and the info line (Rule 124).
233	const pathFooterHeight = 5
234	
235	// GetFooterHeight implements FooterView — tab bar + empty + info + ports filter bar when visible (Rule 124)
236	func (m *Model) GetFooterHeight() int {
237		if m.activeTab == tabPath {
238			return pathFooterHeight
239		}
240		if m.activeTab == tabPorts {
241			return 3 + m.portsModel.table.FilterBar().ExtraHeight()
242		}
243		if m.activeTab == tabDiagnostics {
244			return 3 + m.filterBar.ExtraHeight()
245		}
246		if m.activeTab == tabInterfaces {
247			return 3 + m.interfacesModel.table.FilterBar().ExtraHeight()
248		}
249		if m.activeTab == tabForward {
250			return 3 + m.forwardModel.table.FilterBar().ExtraHeight()
251		}
252		return 3
253	}
254	
255	// RenderFooter implements FooterView
256	func (m *Model) RenderFooter(width int) string {
257		var parts []string
258	
259		// The active tab's filter bar renders above the tab bar when visible; on
260		// Path the target field takes that slot in every state.
261		switch {
262		case m.activeTab == tabPath:
263			parts = append(parts, m.pathModel.barView(width))
264		case m.activeTab == tabPorts && m.portsModel.table.FilterBar().IsVisible():
265			parts = append(parts, m.portsModel.table.FilterBar().View())
266		case m.activeTab == tabDiagnostics && m.filterBar.IsVisible():
267			parts = append(parts, m.filterBar.View())
268		case m.activeTab == tabInterfaces && m.interfacesModel.table.FilterBar().IsVisible():
269			parts = append(parts, m.interfacesModel.table.FilterBar().View())
270		case m.activeTab == tabForward && m.forwardModel.table.FilterBar().IsVisible():
271			parts = append(parts, m.forwardModel.table.FilterBar().View())
272		}
273	
274		tabs := theme.RenderTabs([]theme.TabItem{
275			{Label: "Diagnostics"},
276			{Label: "Ports"},
277			{Label: "Interfaces"},
278			{Label: "Forward"},
279			{Label: "Path"},
280		}, m.activeTab)
281		tabBar := theme.PadWithBg(theme.Bg(" ")+tabs, width)
282	
283		// The message belongs to the tab that raised it: each sub-model keeps its
284		// own, so switching away does not carry one tab's notice onto another.
285		footer, status := m.activeFooter()
286		parts = append(parts, tabBar, theme.EmptyLineBg(width), footer.View(width, status))
287		return strings.Join(parts, "\n")
288	}
289	
290	// activeFooter resolves the message line of whichever tab is on screen, and the
291	// status that tab derives on every frame.
292	func (m *Model) activeFooter() (*components.FooterMessage, components.Status) {
293		switch m.activeTab {
294		case tabPorts:
295			return &m.portsModel.footer, m.portsModel.statusLine()
296		case tabInterfaces:
297			return &m.interfacesModel.footer, m.interfacesModel.statusLine()
298		case tabForward:
299			return &m.forwardModel.footer, m.forwardModel.status()
300		case tabPath:
301			return &m.pathModel.footer, m.pathModel.statusLine()
302		}
303		if m.state == StateTrace {
304			return &m.pathModel.footer, m.pathModel.statusLine()
305		}
306		return &m.footer, m.statusLine()
307	}
308	
309	// statusLine is what the diagnostics tab derives on every frame: a progress
310	// label while the pipeline walks, and nothing once it has an answer. It is a
311	// status rather than a footer message because it is a state, not an event —
312	// a message expires after three seconds and a run outlives that (Rule 128).
313	func (m *Model) statusLine() components.Status {
314		if m.state == StateRunning {
315			return components.Status{Text: m.progressLabel(), Activity: true}
316		}
317		if m.state == StateInput {
318			if st := m.traceValidation.Status(); st.Text != "" {
319				return st
320			}
321		}
322		if m.state == StateInput {
323			if a := m.traceable(); !a.Enabled() {
324				return components.Status{Text: a.Reason, Level: components.LevelWarning}
325			}
326		}
327		return components.Status{}
328	}
