330	// GetHelpContent implements help.Provider
331	func (m *Model) GetHelpContent() help.Content {
332		return help.Content{
333			Title:       "Network",
334			Description: "Five-tab view: check whether a host is reachable and its certificate chain sound (Diagnostics), monitor live ports (Ports), inspect this machine's network interfaces (Interfaces), or redirect a local port to a host:port, or give a service a name (Forward), or trace the hops a packet takes to a host (Path).",
335			KeyBindings: []help.KeyBinding{
336				// Tab navigation
337				{Key: "tab / shift+tab", Description: "Cycle between the Diagnostics, Ports, Interfaces, Forward and Path tabs"},
338				// Diagnostics
339				{Key: "↑ / ↓", Description: "Navigate between fields (Diagnostics tab)"},
340				{Key: "enter (form)", Description: "Run the checks against the target"},
341				{Key: "esc (running)", Description: "Cancel the run and keep what completed"},
342				{Key: "enter (results)", Description: "Explain the selected check"},
343				{Key: "p", Description: "Show problems only / show every check (Diagnostics tab)"},
344				{Key: "/", Description: "Search checks by name or observation (Diagnostics tab)"},
345				{Key: keymap.Diagnose + " (results)", Description: "Trace the path to the target: on the Local route row, opens the Path tab with the host filled in (Diagnostics tab)"},
346				{Key: "ctrl+r", Description: "Run the checks again"},
347				{Key: "esc (results)", Description: "Back to the target form, or back to wherever this run was opened from (e.g. status's H) when it was opened prefilled"},
348				{Key: keymap.New + " (results)", Description: "Start a new diagnostic — always resets to the form, even when esc there means \"go back\""},
349				{Key: "esc (details)", Description: "Back to the checks"},
350				{Key: "pgup / pgdown", Description: "Scroll half page up / down"},
351				// Ports tab
352				{Key: "t", Description: "Toggle TCP filter — cumulative with u (Ports tab)"},
353				{Key: "u", Description: "Toggle UDP filter — cumulative with t (Ports tab)"},
354				{Key: "l", Description: "Toggle LISTEN state filter — cumulative with e (Ports tab)"},
355				{Key: "e", Description: "Toggle ESTAB state filter — cumulative with l (Ports tab)"},
356				{Key: "n", Description: "Toggle numeric addresses / reverse-DNS host names (Ports tab)"},
357				{Key: "z", Description: "Reset all active filters (Ports tab)"},
358				{Key: "/", Description: "Search ports by address, process or PID (Ports tab)"},
359				{Key: "space (Ports)", Description: "Pause / resume auto-refresh (Ports tab)"},
360				{Key: keymap.Kill, Description: "Send SIGKILL to the selected process, after confirmation (Ports tab)"},
361				// Interfaces tab
362				{Key: "/", Description: "Search interfaces by name, MAC or address (Interfaces tab)"},
363				{Key: ".", Description: "Cycle the sort column (Interfaces tab)"},
364				{Key: "ctrl+r", Description: "Re-read the interfaces (Interfaces tab)"},
365				// Forward tab
366				{Key: keymap.New, Description: "Open a new forward — TCP, or a named HTTP route (Forward tab)"},
367				{Key: "space", Description: "Pause the selected forward, or resume a paused or unbound one (Forward tab)"},
368				{Key: keymap.Kill, Description: "Delete the selected forward, after confirmation (Forward tab)"},
369				{Key: "/", Description: "Search forwards by port or target (Forward tab)"},
370				{Key: ".", Description: "Cycle the sort column (Forward tab)"},
371				// Path tab
372				{Key: "enter (Path)", Description: "Trace the path to the target typed in the field, or trace again once a trace is done (Path tab)"},
373				{Key: "esc (Path, running)", Description: "Cancel the trace and keep the hops already seen (Path tab)"},
374				{Key: "esc (Path, done)", Description: "Edit the target again, keeping its value (Path tab)"},
375				{Key: "enter (Trace Path button)", Description: "Trace the path to the form's target in a sub-level of the Diagnostics tab (Diagnostics tab)"},
376				{Key: "esc (trace)", Description: "Cancel a running trace; once it ended, go back to the form with its fields kept (Diagnostics tab)"},
377				{Key: "ctrl+o (Path)", Description: "Choose where the trace starts: this machine or a running container; ↑↓ to move, enter to choose, esc to close (Path tab)"},
378			},
379			Sections: []help.Section{
380				{
381					Title: "Diagnostics Tab — What it asks",
382					Body: "One target, one run. The checks follow from the target and from what has " +
383						"already failed, so there is nothing to select.\n\n" +
384						"DNS resolution     - the name, against the resolver your own traffic uses\n" +
385						"Reverse DNS        - the name an address publishes (literal targets only)\n" +
386						"Local route        - which interface carries this target, and from which address\n" +
387						"ICMP echo          - reachability; a filtered echo is a warning, never a failure\n" +
388						"TCP connect        - the port you named, and the answer that decides reachability\n" +
389						"TLS handshake      - whether the port speaks TLS at all\n" +
390						"Certificate chain  - verified against this machine's store, intermediates included\n" +
391						"Hostname match     - whether the certificate names the host you dialled\n" +
392						"Certificate expiry - the validity window, in days\n" +
393						"TLS version        - the negotiated protocol version\n" +
394						"HTTP response      - whether the service answers, over the scheme actually spoken",
395				},
396				{
397					Title: "Diagnostics Tab — Reading the verdicts",
398					Body: "OK      - the objective is met\n" +
399						"WARN    - met, but something is off: a certificate near expiry, a deprecated\n" +
400						"          version, a chain that verifies here and will not elsewhere\n" +
401						"FAIL    - the objective is not met\n" +
402						"N/A     - no meaning for this target, or blocked by a check above it\n" +
403						"UNKNOWN - the check could not look, which is not the same as a pass\n\n" +
404						"A stage whose dependency failed does not run: its checks come back N/A naming " +
405						"what blocked them, so a broken run reads as one failure and a named point of " +
406						"rupture rather than as ten red rows.\n\n" +
407						"Press enter on any row for what it means and what to do about it.",
408				},
409				indicator.Legend(),
410				{
411					Title: "Ports Tab — How it works",
412					Body: "Reads this machine's TCP and UDP sockets every 2 seconds, in this process — no " +
413						"container, no Docker. Shows the owning process name and PID where the system will " +
414						"name one. K terminates that process, after a confirmation, with the rights DevDesk " +
415						"itself has: another user's process or a service comes back refused rather than " +
416						"silently killed elsewhere.\n\n" +
417						"n toggles reverse DNS on the addresses. Host names only — port numbers stay " +
418						"numeric, because a service name would be DevDesk's guess and not the system's.\n\n" +
419						"While K is killing a process, the dot on its sockets (" + indicator.Glyph(indicator.Running, true) +
420						") is lit and the footer names the kill.",
421				},
422				{
423					Title: "Forward Tab — How it works",
424					Body: "Redirects traffic to a host:port, inside this process — no privilege, " +
425						"no container, nothing written to a system file. Use it to reach a port nothing " +
426						"published: a container's EXPOSEd port, or a service on another machine.\n\n" +
427						"N opens a form with a Type field, changed with ← →. TCP redirects a local port " +
428						"to a host:port. HTTP gives the target a name instead of a port: fill in Name " +
429						"and Target, and http://<name>:<proxy port> reaches it.\n\n" +
430						"A name must end in .localhost, such as api.localhost — nothing else is " +
431						"accepted. That suffix is reserved for this machine, so it needs no DNS entry and " +
432						"no privilege; any other name would not resolve. Every named route is served on " +
433						"the same port, network.proxy_port (8080 by default, in the network tab of the " +
434						"configuration), and the request's Host header picks the target — so " +
435						"http://api.localhost:8080 and http://app.localhost:8080 are two services on one " +
436						"port. The port stays in the URL because 80 is privileged. It is HTTP only: " +
437						"https would need a certificate your browser trusts. A name that is not known " +
438						"gets a page listing the ones that are.\n\n" +
439						"Everything listens on 127.0.0.1 only, so it is available to this machine and " +
440						"not to the network — a service kept off the LAN stays off it. A TCP forward's " +
441						"local port has to be 1024 or above, and cannot be the proxy's: anything below " +
442						"needs privileges DevDesk does not ask for, and there is no unprivileged way " +
443						"around that on Linux or macOS.\n\n" +
444						"The target is dialled once before the port is bound, so an address that answers " +
445						"nothing is refused immediately instead of failing later at the first client. A " +
446						"container's own address is reachable from the host on native Linux; under " +
447						"Docker Desktop it lives in the virtual machine and does not route out of it.\n\n" +
448						"Forwards are saved in ~/.devdesk/forwards.yaml and reopened when DevDesk " +
449						"starts. They survive a context switch — a local port pointed at a host:port " +
450						"belongs to no context — but the listener itself cannot outlive the process, so " +
451						"what comes back is the list, bound again.\n\n" +
452						"A forward that cannot be bound at launch — its port is taken, or its target is " +
453						"not up yet — is not deleted. Its row reads unbound, the last error says why, and " +
454						"space tries again. Space also pauses a live forward: the port is released and the " +
455						"row stays, paused, until you resume it. K deletes a forward for good, and asks " +
456						"first.",
457				},
458				{
459					Title: "Path Tab — How it works",
460					Body: "Traces the hops between this machine and a target, in this process — no " +
461						"container, no traceroute binary. Native Linux and WSL2 only: on macOS, Windows and WSL1 the tab says so " +
462						"and enter and ctrl+o are greyed out. IPv4 only: a host name is resolved to its IPv4 address. " +
463						"The column starts on this machine: the interface the target's traffic leaves by, " +
464						"with its source address, and the gateway, read from this machine's routing table, " +
465						"then the hops. Under WSL2 the source row names the WSL2 VM, and in NAT mode the " +
466						"first hop through the virtual switch is labelled Windows host.\n\n" +
467						"Type a host name or an IPv4 address, and press enter; a port is refused because " +
468						"the trace probes a host, not a service. Each hop is a UDP datagram sent to UDP " +
469						"port 33435 with a growing time-to-live; the router that drops it answers, and the " +
470						"table fills in as the answers come. No connection is made. Nothing is sent before you " +
471						"press enter.\n\n" +
472						"A silent hop is not a failure: many routers do not answer these probes, so the row " +
473						"reads silent and the trace goes on. The header says how a trace ended.\n\n" +
474						"When the target never answers, the silent hops at the end fold into one row, " +
475						"no response beyond hop N, and the last hop that answered reads last to answer. " +
476						"When this machine has no route to the target, the interface row reads no route " +
477						"and nothing is sent; undetermined means the routing table could not be read, " +
478						"which says nothing either way. DevDesk shows only what came back: it does not " +
479						"say why the rest stayed silent.\n\n" +
480						"ctrl+o opens Trace from: this machine, or a running container (Docker Engine on " +
481						"Linux only). The column then starts with the container, its network and the " +
482						"gateway it uses, and a row says the probes still leave from this machine: " +
483						"nothing runs inside the container.\n\n" +
484						"Docker Desktop and podman are not offered. With no running container, only this " +
485						"machine is offered. Reading the engine (ps, info, inspect) starts nothing. An " +
486						"engine reached through DOCKER_HOST or a remote context is not detected as remote: " +
487						"it can show another machine's network, and the trace still leaves from this machine.\n\n" +
488						"The bridge row appears only when this machine has the interface of the container's " +
489						"network bridge, read on this machine; otherwise no bridge is shown. A remote engine " +
490						"whose network is also called docker0 can match this machine's interface by name.\n\n" +
491						"When the container's bridge is not on this machine, the engine row reads " +
492						"internal path not visible (location unknown): the engine may run in a VM, remote " +
493						"or rootless, and DevDesk does not guess. When it cannot check, the row reads " +
494						"undetermined (bridge not verified). The hops are traced from this machine (the " +
495						"host, or the WSL VM when DevDesk runs under WSL); DevDesk cannot see inside the " +
496						"engine's VM.",
497				},
498				{
499					Title: "Interfaces Tab — How it works",
500					Body: "Lists this machine's network interfaces, read in this process — no container, " +
501						"no Docker. Name, state, MTU, hardware address, error counters and every address " +
502						"the interface carries. ctrl+r re-reads them.\n\n" +
503						"A dash is not a zero. RX err and TX err show a dash when the counters could not " +
504						"be read at all, which is a different thing from an interface that has dropped " +
505						"nothing; MTU shows one where the platform reports no figure, as Windows does " +
506						"for its loopback.\n\n" +
507						"This was the Topology tab. Its routing table, ARP cache and firewall summary " +
508						"were read by running ip and iptables in a container on the Docker Desktop VM, " +
509						"so they described the VM and not this machine. Nothing portable produces them, " +
510						"so they were removed rather than translated — and the route question moved to " +
511						"the Diagnostics tab, where it is asked about a target: the Local route check " +
512						"names the interface your traffic to that host actually leaves by.",
513				},
514				{
515					Title: "Where the checks run",
516					Body: "Everything here runs in this process, on this machine's network stack: the " +
517						"diagnostic checks, the socket table, the interfaces and the path trace alike. They answer for " +
518						"the resolver, the routing table, the sockets and the VPN you are actually on, " +
519						"and nothing needs Docker.\n\n" +
520						"The route trace used to be the exception. It ran traceroute in a container " +
521						"started with --network host, which on Docker Desktop is the Linux VM's " +
522						"namespace — so it traced the path from the VM and not from here, and the two " +
523						"are not the same network. It was removed rather than kept with a caveat.\n\n" +
524						"The trace is back, in this process: the Path tab sends its own probes from this " +
525						"machine's network stack, so it answers for the network you are actually on. The " +
526						"Local route check still names the interface and source address your traffic to a " +
527						"target leaves by — the split-tunnel answer, read from this machine.",
528				},
529			},
530		}
531	}
